<template>
 <section class="cp" aria-label="选择预测客户">
  <div class="cp-heading"><span>客户范围 <small>可多选</small></span><b>已选 {{modelValue.length}} 个</b></div>
  <label class="cp-search"><GraphIcon name="search"/><input v-model="query" aria-label="搜索预测客户" placeholder="搜索客户、地区或行业"></label>
  <div class="cp-actions"><span>{{filtered.length}} 个客户</span><button type="button" :disabled="!filtered.length" @click="selectMatches">全选搜索结果</button><button type="button" :disabled="!modelValue.length" @click="$emit('update:modelValue',[])">清空</button></div>
  <div class="cp-options"><label v-for="customer in visible" :key="customer.id"><input type="checkbox" :checked="modelValue.includes(customer.id)" :aria-label="'选择客户：'+customer.name" @change="toggle(customer.id)"><span><b>{{customer.name}}</b><small>{{[customer.region,customer.industry].filter(Boolean).join(' · ')||'已配置客户'}}</small></span></label><p v-if="!filtered.length">暂无匹配客户</p><button v-if="visible.length<filtered.length" type="button" class="cp-more" @click="limit+=40">显示更多（{{visible.length}} / {{filtered.length}}）</button></div>
  <div v-if="selected.length" class="cp-selected"><span v-for="customer in selected.slice(0,4)" :key="customer.id">{{customer.name}}<button type="button" :aria-label="'移除客户：'+customer.name" @click="toggle(customer.id)"><GraphIcon name="close"/></button></span><small v-if="selected.length>4">另 {{selected.length-4}} 个</small></div>
 </section>
</template>
<script setup>
import {ref,computed,watch} from 'vue'
import GraphIcon from './GraphIcon.vue'
const props=defineProps({options:{type:Array,default:()=>[]},modelValue:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue'])
const query=ref(''),limit=ref(40)
const filtered=computed(()=>{const term=query.value.trim().toLowerCase();return props.options.filter(customer=>[customer.name,customer.region,customer.industry].join(' ').toLowerCase().includes(term))})
const visible=computed(()=>filtered.value.slice(0,limit.value)),selected=computed(()=>props.options.filter(customer=>props.modelValue.includes(customer.id)))
watch(query,()=>limit.value=40)
function toggle(id){emit('update:modelValue',props.modelValue.includes(id)?props.modelValue.filter(value=>value!==id):[...props.modelValue,id])}
function selectMatches(){emit('update:modelValue',[...new Set([...props.modelValue,...filtered.value.map(customer=>customer.id)])])}
</script>
<style scoped>
.cp{border:1px solid var(--wb-ui-border);border-radius:9px;background:var(--wb-ui-surface-raised);padding:12px;color:var(--wb-ui-secondary);font-size:var(--wb-font-meta)}.cp-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.cp-heading small{margin-left:4px;color:var(--wb-ui-text);font-size:var(--wb-font-meta)}.cp-heading>b{font-size:var(--wb-font-meta);color:var(--wb-ui-text);font-weight:400}.cp-search{display:flex!important;align-items:center;gap:6px;padding:0 8px!important;margin:0!important;border:1px solid var(--wb-ui-border);border-radius:6px;background:var(--wb-ui-surface)}.cp-search svg{width:13px;height:13px;flex-shrink:0;color:var(--wb-ui-muted)}.cp-search input{min-width:0;width:100%;padding:7px 0!important;border:0!important;outline:0!important;border-radius:0!important;background:transparent!important;color:var(--wb-ui-text);font:inherit;font-size:var(--wb-font-meta)!important;margin:0!important}.cp-actions{display:flex;align-items:center;gap:10px;margin:10px 0;color:var(--wb-ui-muted);font-size:var(--wb-font-meta)}.cp-actions span{margin-right:auto}.cp-actions button,.cp-more{padding:0;border:0;background:none;color:var(--wb-ui-secondary);font:inherit;font-size:var(--wb-font-meta);cursor:pointer}.cp-actions button:disabled{opacity:.4;cursor:default}.cp-options{max-height:180px;overflow:auto;scrollbar-width:thin;scrollbar-color:var(--wb-ui-border-strong) transparent}.cp-options>label{display:flex!important;align-items:center;gap:8px;padding:7px 3px!important;margin:0!important;border-bottom:1px solid var(--wb-ui-border);cursor:pointer}.cp-options>label:hover{background:var(--wb-ui-selection)}.cp-options input{display:block!important;width:14px!important;height:14px;margin:0!important;padding:0!important;accent-color:#4e9873;flex-shrink:0}.cp-options>label>span{min-width:0}.cp-options b{display:block;color:var(--wb-ui-text);font-size:var(--wb-font-meta);font-weight:400;overflow-wrap:anywhere}.cp-options small{display:block;color:var(--wb-ui-muted);font-size:var(--wb-font-meta);margin-top:3px}.cp-options>p{text-align:center;padding:15px;color:var(--wb-ui-muted);font-size:var(--wb-font-meta)}.cp-more{display:block;margin:10px auto}.cp-selected{display:flex;flex-wrap:wrap;align-items:center;gap:5px;margin-top:10px}.cp-selected>span{display:inline-flex;align-items:center;gap:4px;max-width:100%;padding:3px 5px;border:1px solid var(--wb-ui-border);border-radius:4px;background:var(--wb-ui-selection);color:var(--wb-ui-secondary);font-size:var(--wb-font-meta)}.cp-selected button{display:grid;place-items:center;width:12px;height:13px;padding:0;border:0;background:none;color:var(--wb-ui-muted);cursor:pointer}.cp-selected svg{width:9px;height:9px}.cp-selected>small{font-size:var(--wb-font-meta);color:var(--wb-ui-muted)}
</style>
